"""Hard and soft checker helpers for the turn-based judge.

Ported from ``gaia2.validation.tool_judge`` and ``gaia2.validation.utils``.
Optional deps: ``jinja2`` (prompt templates). It gracefully degrades when
unavailable.
"""
import os
import re
import unicodedata
from datetime import datetime, timezone
from typing import Any, Callable

def _normalize_str(s: str) -> str:
    """Normalise a string: lowercase, remove accents, strip punctuation.

    Matches ``gaia2.validation.utils.misc.normalize_str``.
    """
    s = s.lower()
    s = ''.join((c for c in unicodedata.normalize('NFD', s) if unicodedata.category(c) != 'Mn'))
    s = ''.join((c for c in s if c not in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'))
    return s.strip()

def normalize_arg(arg: Any) -> str:
    """Normalise an argument for equality comparison.

    Matches ``gaia2.validation.utils.misc.normalize_arg``.
    """
    return _normalize_str(str(arg))

def extract_text_between_tags(text: str, tag: str) -> list[str]:
    """Extract text between ``<tag>...</tag>`` using regex (replaces bs4 dep)."""
    pattern = re.compile(f'<{tag}>(.*?)</{tag}>', re.DOTALL)
    return pattern.findall(text)

def jinja_format(template, **kwargs):
    parts = re.split('\\{\\{\\s*(\\w+)\\s*\\}\\}', template)
    return ''.join((str(kwargs.get(value, '')) if i % 2 else value for i, value in enumerate(parts)))

def eq_checker(x_agent: Any, x_oracle: Any, **kwargs: Any) -> bool:
    """Exact equality."""
    return x_agent == x_oracle

def unordered_list_checker(x_agent: list[Any] | None, x_oracle: list[Any] | None, **kwargs: Any) -> bool:
    """Set equality; treats ``None`` as empty."""
    if x_agent is None:
        return x_oracle is None or len(x_oracle) == 0
    if x_oracle is None:
        return x_agent is None or len(x_agent) == 0
    return set(x_agent) == set(x_oracle)

def path_checker(x_agent: str | None, x_oracle: str | None, **kwargs: Any) -> bool:
    """Compare after ``os.path.normpath`` + leading-``/`` strip."""
    if not x_agent and (not x_oracle):
        return True
    if not x_agent or not x_oracle:
        return False
    normalized_agent = os.path.normpath(x_agent).lstrip('/')
    normalized_oracle = os.path.normpath(x_oracle).lstrip('/')
    return normalized_agent == normalized_oracle

def unordered_path_list_checker(x_agent: list[str] | None, x_oracle: list[str] | None, **kwargs: Any) -> bool:
    """Set of normalised paths."""
    if x_agent is None:
        return x_oracle is None or len(x_oracle) == 0
    if x_oracle is None:
        return x_agent is None or len(x_agent) == 0
    normalized_agent_paths = {os.path.normpath(path).lstrip('/') for path in x_agent}
    normalized_oracle_paths = {os.path.normpath(path).lstrip('/') for path in x_oracle}
    return normalized_agent_paths == normalized_oracle_paths

def _unordered_str_list_with_tolerance_checker(x_agent: list[str] | None, x_oracle: list[str] | None, tolerance_list_str: list[str] | None=None, **kwargs: Any) -> bool:
    """Normalise strings, remove tolerance items, compare sets."""
    if tolerance_list_str is None:
        tolerance_list_str = []
    _x_agent = [_normalize_str(x) for x in x_agent] if x_agent is not None else []
    _x_oracle = [_normalize_str(x) for x in x_oracle] if x_oracle is not None else []
    _x_agent = [x for x in _x_agent if x not in tolerance_list_str]
    _x_oracle = [x for x in _x_oracle if x not in tolerance_list_str]
    return set(_x_agent) == set(_x_oracle)

def list_attendees_checker(x_agent: list[str] | None, x_oracle: list[str] | None, tolerance_list_str: list[str] | None=None, **kwargs: Any) -> bool:
    """Tolerance-aware unordered string-list comparison."""
    if tolerance_list_str is None:
        tolerance_list_str = []
    _tolerance_list = [_normalize_str(x) for x in tolerance_list_str]
    if x_oracle is None or len(x_oracle) == 0:
        return True
    if all((_normalize_str(x_oracle[i]) in _tolerance_list for i in range(len(x_oracle)))):
        return True
    return _unordered_str_list_with_tolerance_checker(x_agent, x_oracle, _tolerance_list)

def datetime_checker(x_agent: str | None, x_oracle: str | None, **kwargs: Any) -> bool:
    """Parse ``%Y-%m-%d %H:%M:%S`` and compare."""
    if x_agent is None or x_oracle is None:
        return x_agent == x_oracle
    _x_agent = datetime.strptime(x_agent, '%Y-%m-%d %H:%M:%S')
    _x_oracle = datetime.strptime(x_oracle, '%Y-%m-%d %H:%M:%S')
    return _x_agent == _x_oracle

def eq_str_strip_checker(x_agent: str | None, x_oracle: str | None, **kwargs: Any) -> bool:
    """Strip + equality."""
    _x_agent = x_agent.strip() if bool(x_agent) else ''
    _x_oracle = x_oracle.strip() if bool(x_oracle) else ''
    return _x_agent == _x_oracle

def phone_number_checker(x_agent: str | None, x_oracle: str | None, **kwargs: Any) -> bool:
    """Digits-only comparison; treats ``None`` and ``""`` as equivalent."""
    _x_agent = ''.join((char for char in x_agent if char.isdigit())) if x_agent else ''
    _x_oracle = ''.join((char for char in x_oracle if char.isdigit())) if x_oracle else ''
    return _x_agent == _x_oracle

def contain_any_checker(x_agent: str, targets: list[str], **kwargs: Any) -> bool:
    """Case-insensitive substring match (any target)."""
    return any((x_oracle.lower() in x_agent.lower() for x_oracle in targets))

def contain_all_checker(x_agent: str, targets: list[str], **kwargs: Any) -> bool:
    """Case-insensitive substring match (all targets)."""
    return all((x_oracle.lower() in x_agent.lower() for x_oracle in targets))
_HARD_CHECKERS: dict[str, Callable] = {'eq_checker': eq_checker, 'unordered_list_checker': unordered_list_checker, 'datetime_checker': datetime_checker, 'list_attendees_checker': list_attendees_checker, 'phone_number_checker': phone_number_checker, 'eq_str_strip_checker': eq_str_strip_checker, 'path_checker': path_checker, 'unordered_path_list_checker': unordered_path_list_checker, 'contain_any_checker': contain_any_checker, 'contain_all_checker': contain_all_checker}

def hard_compare(agent_args: dict[str, Any], oracle_args: dict[str, Any], arg_to_checker_type: dict[str, CheckerType], tolerance_list_str: list[str] | None=None) -> tuple[bool, str]:
    """Run hard checkers on all registered args.

    Returns:
        ``(passed, rationale)`` — rationale is empty string on success.
    """
    for arg_name, check_type in arg_to_checker_type.items():
        if not check_type in ['datetime_checker', 'eq_checker', 'eq_str_strip_checker', 'list_attendees_checker', 'path_checker', 'phone_number_checker', 'unordered_list_checker', 'unordered_path_list_checker'] and (not check_type in ['contain_all_checker', 'contain_any_checker']):
            continue
        checker_fn = _HARD_CHECKERS.get(check_type)
        if checker_fn is None:
            continue
        agent_val = agent_args.get(arg_name)
        oracle_val = oracle_args.get(arg_name)
        extra_kwargs: dict[str, Any] = {'arg_name': arg_name}
        if check_type == 'list_attendees_checker':
            extra_kwargs['tolerance_list_str'] = tolerance_list_str
        if check_type in ['contain_all_checker', 'contain_any_checker']:
            if not checker_fn(agent_val, oracle_val, **extra_kwargs):
                return (False, f'{check_type}:{arg_name} (agent={agent_val})')
        elif not checker_fn(x_agent=agent_val, x_oracle=oracle_val, **extra_kwargs):
            return (False, f'{check_type}:{arg_name} (agent={agent_val}, oracle={oracle_val})')
    return (True, '')

class LLMFunction:
    """Format prompts and call LLM engine.  Returns raw string."""

    def __init__(self, engine: Callable, prompt_templates: Any) -> None:
        system_prompt_args = prompt_templates.system_prompt_args or {}
        self.system_prompt = jinja_format(prompt_templates.system_prompt_template, **system_prompt_args)
        self.user_prompt_template = prompt_templates.user_prompt_template
        self.examples: list[dict[str, str]] = []
        if prompt_templates.assistant_prompt_template and prompt_templates.examples:
            for example in prompt_templates.examples:
                self.examples.extend([{'role': 'user', 'content': jinja_format(self.user_prompt_template, **example['input'])}, {'role': 'assistant', 'content': jinja_format(prompt_templates.assistant_prompt_template, **example['output'])}])
        self.engine = engine

    def __call__(self, user_prompt_args: dict[str, str]) -> str | None:
        messages: list[dict[str, str]] = [{'role': 'system', 'content': self.system_prompt}]
        messages.extend(self.examples)
        user_prompt = jinja_format(self.user_prompt_template, **user_prompt_args)
        messages.append({'role': 'user', 'content': user_prompt})
        response, _ = self.engine(messages)
        return response

class LLMChecker:
    """Majority-vote LLM checker.  Returns ``bool`` or ``None``."""

    def __init__(self, engine: Callable, prompt_templates: Any, num_votes: int=1, success_str: str='[[Success]]', failure_str: str='[[Failure]]') -> None:
        self.judge = LLMFunction(engine=engine, prompt_templates=prompt_templates)
        self.num_votes = num_votes
        self.success_str = success_str
        self.failure_str = failure_str
        self.last_response: str | None = None

    def __call__(self, user_prompt_args: dict[str, str]) -> bool | None:
        votes: list[bool] = []
        for _ in range(self.num_votes):
            response = self.judge(user_prompt_args)
            self.last_response = response
            if response is None:
                pass
                continue
            response_lower = response.lower()
            if self.success_str.lower() in response_lower:
                votes.append(True)
            elif self.failure_str.lower() in response_lower:
                votes.append(False)
                pass
            else:
                pass
        if not votes:
            return None
        result = sum(votes) >= len(votes) / 2
        pass
        return result

def build_llm_checkers(engine: Callable, num_votes: int=1, *, prompt_template_overrides: dict | None=None) -> dict[str, LLMChecker]:
    """Build all LLM checker instances.

    ``prompt_template_overrides`` maps a ``SoftCheckerType`` value to the
    ``LLMFunctionTemplates`` to use for that checker instead of the default.
    """
    checkers = {'signature_checker': LLMChecker(engine, SIGNATURE_CHECKER_TEMPLATES, 1, '[[True]]', '[[False]]'), 'sanity_checker': LLMChecker(engine, SANITY_CHECKER_PROMPT_TEMPLATES, 1, '[[True]]', '[[False]]'), 'content_checker': LLMChecker(engine, CONTENT_CHECKER_PROMPT_TEMPLATES, num_votes), 'cab_checker': LLMChecker(engine, CAB_CHECKER_PROMPT_TEMPLATES, 1, '[[True]]', '[[False]]'), 'email_checker': LLMChecker(engine, EMAIL_CHECKER_PROMPT_TEMPLATES, num_votes), 'message_checker': LLMChecker(engine, MESSAGE_CHECKER_PROMPT_TEMPLATES, num_votes), 'user_message_checker': LLMChecker(engine, USER_MESSAGE_CHECKER_PROMPT_TEMPLATES, num_votes), 'event_checker': LLMChecker(engine, EVENT_CHECKER_PROMPT_TEMPLATES, num_votes), 'tone_checker': LLMChecker(engine, TONE_CHECKER_PROMPT_TEMPLATES, num_votes, '[[True]]', '[[False]]')}
    for key, templates in (prompt_template_overrides or {}).items():
        old = checkers[key]
        checkers[key] = LLMChecker(engine, templates, old.num_votes, old.success_str, old.failure_str)
    return checkers

def build_subtask_extractor(engine: Callable, tool_name: str) -> LLMFunction:
    """Build the subtask extractor for a given tool."""
    templates = SUBTASK_EXTRACTOR_PROMPT_TEMPLATES
    if 'add_calendar_event' in tool_name:
        templates = EVENT_SUBTASK_EXTRACTOR_PROMPT_TEMPLATES
    elif tool_name == 'AgentUserInterface__send_message_to_user':
        templates = USER_MESSAGE_SUBTASK_EXTRACTOR_PROMPT_TEMPLATES
    return LLMFunction(engine=engine, prompt_templates=templates)

def placeholder_checker(agent_args: dict[str, Any], **kwargs: Any) -> bool:
    """Check for leftover placeholders in agent args."""
    agent_args_str = ' '.join((str(v) for v in agent_args.values()))
    placeholders = ["[User's Name]", '[User Name]', '[User]', '[Your Name]', '[My Name]', 'Best regards,\nYour Name', 'Best,\nYour Name']
    return not any((p.lower() in agent_args_str.lower() for p in placeholders))

def _describe_action_args(args: dict[str, Any]) -> str:
    """Format args for LLM prompt display."""
    return '\n'.join((f'{k}: {v}' for k, v in args.items())).strip()

def _equality_checker(agent_args: dict[str, Any], oracle_args: dict[str, Any]) -> bool:
    """Normalised equality across all oracle arg keys."""
    for arg_name in oracle_args:
        if arg_name not in agent_args:
            return False
        if normalize_arg(agent_args[arg_name]) != normalize_arg(oracle_args[arg_name]):
            return False
    return True

def soft_compare(agent_args: dict[str, Any], oracle_args: dict[str, Any], tool_name: str, soft_checker_types: list[SoftCheckerType], llm_checkers: dict[str, LLMChecker] | None, tasks: list[str] | None=None, user_details: UserDetails | None=None, oracle_event_time: float | None=None, scenario_start_time: float | None=None, engine: Callable | None=None) -> tuple[bool | None, str, str]:
    """Run soft (LLM) checkers.

    Returns:
        ``(passed_or_none, rationale, judge_output)``
    """
    if not soft_checker_types:
        return (True, '', '')
    if _equality_checker(agent_args=agent_args, oracle_args=oracle_args):
        return (True, '', '')
    if llm_checkers is None:
        return (True, 'no LLM, hard-only', '')
    today_date = ''
    effective_time = oracle_event_time
    if effective_time is None or effective_time <= 0:
        effective_time = scenario_start_time
    if effective_time is not None and effective_time > 0:
        today_date = _utc_fromtimestamp(effective_time).strftime('%Y-%m-%d %A')
    user_name = f'{user_details.first_name} {user_details.last_name}' if user_details else ''
    user_address = f'{user_details.address}' if user_details else ''
    if tasks is None:
        tasks = ['']
    task = tasks[-1] if tasks else ''
    previous_task = '\n'.join(tasks[:-1]) if len(tasks) > 1 else ''
    need_subtask = any((c in ['content_checker', 'event_checker', 'sanity_checker', 'user_message_checker'] for c in soft_checker_types))
    subtask = ''
    if need_subtask and engine is not None:
        subtask_extractor = build_subtask_extractor(engine=engine, tool_name=tool_name)
        full_task = '\n'.join(tasks).strip()
        if full_task:
            raw = subtask_extractor(user_prompt_args={'tool_name': tool_name, 'oracle_action_call': _describe_action_args(oracle_args), 'task': full_task})
            if raw is not None:
                extracted = extract_text_between_tags(raw, 'subtask')
                subtask = extracted[0].strip() if extracted else ''
    agent_action_call = _describe_action_args(agent_args)
    oracle_action_call = _describe_action_args(oracle_args)
    for checker_type in soft_checker_types:
        result: bool | None = None
        if checker_type == 'placeholder_checker':
            result = placeholder_checker(agent_args=agent_args)
        elif checker_type == 'signature_checker':
            result = llm_checkers['signature_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'user_name': user_name})
        elif checker_type == 'sanity_checker':
            is_numerical = re.match('^content: \\d+(\\.\\d+)?$', agent_action_call)
            if is_numerical:
                result = True
            else:
                result = llm_checkers['sanity_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'task': '\n'.join([previous_task, task])})
        elif checker_type == 'content_checker':
            result = llm_checkers['content_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'oracle_action_call': oracle_action_call, 'task': subtask, 'tool_name': tool_name, 'today_date': today_date, 'user_address': user_address})
        elif checker_type == 'cab_checker':
            _home_variants = ('home', 'my place', 'my address')
            resolved_oracle = dict(oracle_args)
            resolved_agent = dict(agent_args)
            if user_address:
                for args in (resolved_oracle, resolved_agent):
                    for k in ('start_location', 'end_location'):
                        if str(args.get(k, '')).strip().lower() in _home_variants:
                            args[k] = user_address
            resolved_oracle_call = _describe_action_args(resolved_oracle)
            resolved_agent_call = _describe_action_args(resolved_agent)
            result = llm_checkers['cab_checker'](user_prompt_args={'agent_action_call': resolved_agent_call, 'oracle_action_call': resolved_oracle_call, 'user_address': user_address})
        elif checker_type == 'email_checker':
            result = llm_checkers['email_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'oracle_action_call': oracle_action_call, 'today_date': today_date})
        elif checker_type == 'message_checker':
            result = llm_checkers['message_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'oracle_action_call': oracle_action_call, 'today_date': today_date})
        elif checker_type == 'user_message_checker':
            result = llm_checkers['user_message_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'oracle_action_call': oracle_action_call, 'task': subtask})
        elif checker_type == 'event_checker':
            result = llm_checkers['event_checker'](user_prompt_args={'agent_action_call': agent_action_call, 'oracle_action_call': oracle_action_call, 'user_address': user_address, 'task': subtask})
        elif checker_type == 'tone_checker':
            result = llm_checkers['tone_checker'](user_prompt_args={'agent_action_call': agent_action_call})
        judge_output = ''
        if llm_checkers and checker_type in llm_checkers:
            judge_output = llm_checkers[checker_type].last_response or ''
        if result is None:
            return (None, f'{checker_type}:inconclusive', judge_output)
        if not result:
            pass
            return (False, f'{checker_type} (agent_args={agent_args})', judge_output)
    return (True, '', '')

def mild_compare(agent_event: CompletedEvent, oracle_event: OracleEvent, arg_checker_registry: dict[str, dict[str, CheckerType]], soft_checker_registry: dict[str, list[SoftCheckerType]], llm_checkers: dict[str, LLMChecker] | None=None, tolerance_list_str: list[str] | None=None, tasks: list[str] | None=None, user_details: UserDetails | None=None, engine: Callable | None=None, scenario_start_time: float | None=None) -> tuple[bool | None, str, str]:
    """Combined hard + soft comparison.

    Returns:
        ``(passed_or_none, rationale, judge_output)``
    """
    if oracle_event.tool_name() != agent_event.tool_name():
        return (False, f'tool name mismatch: agent={agent_event.tool_name()}, oracle={oracle_event.tool_name()}', '')
    tool_name = oracle_event.tool_name()
    agent_args = agent_event.get_args()
    oracle_args = oracle_event.get_args()
    arg_to_checker_type = arg_checker_registry.get(tool_name, {})
    hard_passed, hard_rationale = hard_compare(agent_args=agent_args, oracle_args=oracle_args, arg_to_checker_type=arg_to_checker_type, tolerance_list_str=tolerance_list_str)
    if not hard_passed:
        return (False, hard_rationale, '')
    soft_checker_types = soft_checker_registry.get(tool_name, [])
    if not soft_checker_types:
        return (True, '', '')
    selected_action_args = [name for name, check_type in arg_to_checker_type.items() if check_type == 'llm_checker']
    if not selected_action_args:
        return (True, '', '')
    selected_action_args = [arg for arg in selected_action_args if bool(oracle_args.get(arg))]
    if not selected_action_args:
        return (True, '', '')
    filtered_oracle = {k: v for k, v in oracle_args.items() if k in selected_action_args}
    filtered_agent = {k: v for k, v in agent_args.items() if k in selected_action_args}
    return soft_compare(agent_args=filtered_agent, oracle_args=filtered_oracle, tool_name=tool_name, soft_checker_types=soft_checker_types, llm_checkers=llm_checkers, tasks=tasks, user_details=user_details, oracle_event_time=oracle_event.event_time, scenario_start_time=scenario_start_time, engine=engine)

"""Lightweight scenario JSON parser.

Parses Gaia2 scenario JSON directly with no app registry or framework imports.
"""
import json
from collections import defaultdict, deque
from typing import Any

def _parse_args(args_list: list[dict[str, Any]]) -> dict[str, Any]:
    """Convert Gaia2 JSON args list to a flat dict.

    Gaia2 format:  [{"name": "to", "value": "alice", "value_type": "str"}, ...]
    Output:       {"to": "alice", ...}

    Mirrors ``Scenario._parse_parameter_value`` from
    ``gaia2/scenarios/scenario.py`` — handles Optional[T] wrappers and
    deserialises list/dict via ``json.loads``.
    """
    import re
    result = {}
    for arg in args_list:
        name = arg['name']
        value = arg.get('value')
        vtype = arg.get('value_type')
        if not vtype:
            if isinstance(value, str) and value.startswith(('[', '{')):
                vtype = 'list' if value.startswith('[') else 'dict'
            else:
                vtype = 'str'
        if value is not None:
            m = re.match('Optional\\[(.+)\\]', vtype)
            base_type = m.group(1) if m else vtype
            base_type = re.sub('\\[.*\\]', '', base_type)
            if isinstance(value, str) and value.startswith('{{'):
                result[name] = value
                continue
            try:
                if base_type == 'int':
                    value = int(value)
                elif base_type == 'float':
                    value = float(value)
                elif base_type == 'bool':
                    value = str(value).lower() in ('true', '1', 't', 'y', 'yes')
                elif base_type in ('list', 'dict'):
                    value = json.loads(value) if isinstance(value, str) else value
            except (ValueError, TypeError, json.JSONDecodeError):
                pass
        result[name] = value
    return result

class ScenarioLoader:
    """Parse a Gaia2 scenario JSON directly.

    No Gaia2 app registry, no framework imports.
    """

    def __init__(self, scenario_path: str) -> None:
        with open(scenario_path) as f:
            data = json.load(f)
        self._data = data
        self._events_raw = data.get('events', [])
        self.app_name_to_class: dict[str, str] = {}
        for app in data.get('apps', []):
            name = app.get('name', '')
            cls = app.get('class_name', name)
            if name:
                self.app_name_to_class[name] = cls
        self.events: list[ScenarioEvent] = []
        self._events_by_id: dict[str, ScenarioEvent] = {}
        self._parse_events()
        self.task: str | None = self._extract_task()
        metadata = data.get('metadata', {}).get('definition', {})
        self.start_time: float = float(metadata.get('start_time') or data.get('start_time') or 0.0)
        self.duration: float = float(metadata.get('duration') or data.get('duration') or 86400.0)
        self.time_increment: float = float(metadata.get('time_increment_in_seconds') or data.get('time_increment_in_seconds') or 1.0)
        self.nb_turns: int = 0
        pass

    def _parse_events(self) -> None:
        """Parse raw JSON events into ScenarioEvent objects."""
        for ev in self._events_raw:
            action = None
            raw_action = ev.get('action')
            if raw_action:
                app_name = raw_action.get('app', '')
                class_name = raw_action.get('class_name', '')
                if not class_name:
                    class_name = self.app_name_to_class.get(app_name, app_name)
                args = _parse_args(raw_action.get('args', []))
                operation_type = (raw_action.get('operation_type') or 'read').lower()
                action = EventAction(app_name=app_name, class_name=class_name, function_name=raw_action.get('function', ''), args=args, operation_type=operation_type)
            event = ScenarioEvent(event_id=ev['event_id'], event_type=ev.get('event_type', ''), event_time=ev.get('event_time'), event_relative_time=ev.get('event_relative_time'), action=action, dependency_ids=ev.get('dependencies', []))
            self.events.append(event)
            self._events_by_id[event.event_id] = event
        for event in self.events:
            for dep_id in event.dependency_ids:
                dep = self._events_by_id.get(dep_id)
                if dep is not None:
                    dep.successor_ids.append(event.event_id)

    def _extract_task(self) -> str | None:
        """Extract the initial user task from the first USER send_message_to_agent event.

        In multi-turn scenarios, events are stored in DAG order (not
        chronological).  The initial user message is the one with no
        dependencies.  Falls back to the first USER event if none have
        empty deps.
        """
        fallback: str | None = None
        for ev in self.events:
            if ev.event_type == 'USER' and ev.action:
                if ev.action.function_name == 'send_message_to_agent':
                    if fallback is None:
                        fallback = ev.action.args.get('content')
                    if not ev.dependency_ids:
                        return ev.action.args.get('content')
        return fallback

    def extract_oracle_data(self, event_id_to_turn_idx: dict[str, int], nb_turns: int) -> tuple[list[list[OracleEvent]], list[dict[str, list[str]]], list[str], UserDetails | None]:
        """Extract oracle data needed by the Judge.

        Uses the already-computed *event_id_to_turn_idx* mapping from
        ``EventProcessor.build_event_id_to_turn_idx()``.

        Returns:
            turn_to_oracle_events: per-turn lists of OracleEvent (topo-sorted)
            turn_to_oracle_graph: per-turn causal graphs {event_id: [parent_ids]}
            tasks: per-turn task strings
            user_details: UserDetails from contacts app initial state (or None)
        """
        agent_events_by_turn: dict[int, list[ScenarioEvent]] = defaultdict(list)
        for ev in self.events:
            if ev.event_type != 'AGENT':
                continue
            tidx = event_id_to_turn_idx.get(ev.event_id)
            if tidx is None:
                continue
            agent_events_by_turn[tidx].append(ev)
        turn_to_oracle_events: list[list[OracleEvent]] = []
        turn_to_oracle_graph: list[dict[str, list[str]]] = []
        for tidx in range(nb_turns):
            turn_events = agent_events_by_turn.get(tidx, [])
            target_ids = {ev.event_id for ev in turn_events}
            graph: dict[str, list[str]] = {eid: [] for eid in target_ids}
            for ev in turn_events:
                graph[ev.event_id] = [dep for dep in ev.dependency_ids if dep in target_ids]
            sorted_ids = _topological_sort(graph)
            oracle_events: list[OracleEvent] = []
            for eid in sorted_ids:
                sev = self._events_by_id[eid]
                oracle_events.append(OracleEvent(event_id=sev.event_id, event_type=sev.event_type, action=sev.action, args=sev.action.args if sev.action else {}, event_time=sev.event_time, event_relative_time=sev.event_relative_time, dependency_ids=list(sev.dependency_ids)))
            turn_to_oracle_events.append(oracle_events)
            turn_to_oracle_graph.append(graph)
        turn_idx_to_task: dict[int, str] = defaultdict(str)
        for ev in self.events:
            if ev.event_type == 'USER' and ev.action and (ev.action.function_name == 'send_message_to_agent'):
                tidx = event_id_to_turn_idx.get(ev.event_id, 0)
                content = ev.action.args.get('content', '')
                if content:
                    turn_idx_to_task[tidx] += content + '\n'
        tasks = [turn_idx_to_task.get(i, '') for i in range(nb_turns)]
        user_details = self._extract_user_details()
        pass
        return (turn_to_oracle_events, turn_to_oracle_graph, tasks, user_details)

    def _extract_user_details(self) -> UserDetails | None:
        """Best-effort extraction of user details from scenario JSON.

        This is a fallback — the daemon dumps ``user_details.json`` from
        the container's runtime contacts state, which is the canonical
        source.  The JSON structure varies across dataset formats, so
        this method checks ``app_state`` (GAIA2) first.
        """
        apps = self._data.get('apps', [])
        for app in apps:
            cls = app.get('class_name', app.get('name', ''))
            if cls not in ('ContactsApp', 'Contacts', 'InternalContacts'):
                continue
            contacts = app.get('app_state', {}).get('contacts', {})
            for contact in contacts.values():
                if contact.get('is_user'):
                    return UserDetails(first_name=contact.get('first_name', ''), last_name=contact.get('last_name', ''), address=contact.get('address', ''))
        return None

def _topological_sort(graph: dict[str, list[str]]) -> list[str]:
    """BFS-based topological sort. *graph* maps event_id → [parent_ids]."""
    in_degree: dict[str, int] = defaultdict(int)
    adj: dict[str, list[str]] = defaultdict(list)
    for node, parents in graph.items():
        for parent in parents:
            adj[parent].append(node)
            in_degree[node] += 1
    queue: deque[str] = deque((node for node in graph if in_degree[node] == 0))
    result: list[str] = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for child in adj[node]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                queue.append(child)
    if len(result) != len(graph):
        raise ValueError('Oracle event graph contains a cycle')
    return result

"""Judge orchestrator — ports GraphPerEventJudge from gaia2.validation.judge.

Called by EventProcessor at each turn boundary to validate agent actions
against oracle expectations.
"""
import json
from collections import Counter
from pathlib import Path
from typing import Any, Callable

class Judge:
    """Per-event judge matching Gaia2 ``GraphPerEventJudge`` semantics.

    Validates that each turn's agent events match the oracle events
    using hard checkers (pure Python) and optional soft checkers (LLM).
    """

    def __init__(self, turn_to_oracle_events: list[list[OracleEvent]], turn_to_oracle_graph: list[dict[str, list[str]]], tasks: list[str], user_details: UserDetails | None=None, start_time: float=0.0, engine: Callable | None=None, extra_send_message_to_user_allowed: int=1, app_name_to_class: dict[str, str] | None=None, state_dir: str | Path | None=None, judge_mode: str='eval', check_time_threshold_seconds: float=1.0, pre_event_tolerance_seconds: float=10.0, post_event_tolerance_seconds: float=25.0, time_check_warn_only: bool=False, prompt_overrides: dict | None=None) -> None:
        self.turn_to_oracle_events = turn_to_oracle_events
        self.turn_to_oracle_graph = turn_to_oracle_graph
        self.tasks = tasks
        self.user_details = user_details
        self.start_time = start_time
        self.extra_smu_allowed = extra_send_message_to_user_allowed
        self.app_name_to_class = app_name_to_class or {}
        self._judgments_path = Path(state_dir) / 'judgments.jsonl' if state_dir else None
        self._check_time_threshold = check_time_threshold_seconds
        self._pre_event_tolerance = pre_event_tolerance_seconds
        self._post_event_tolerance = post_event_tolerance_seconds
        self._time_check_warn_only = time_check_warn_only
        self.env_return_values: dict[str, Any] = {}
        self._arg_registry, self._soft_registry = build_checker_registries(mode=judge_mode)
        self._llm_checkers: dict | None = None
        if engine is not None:
            self._llm_checkers = build_llm_checkers(engine, prompt_template_overrides=prompt_overrides)
        self._all_agent_events: list[CompletedEvent] = []
        self._agent_idx_to_oracle_id: dict[int, str] = {}
        self._oracle_id_to_agent_idx: dict[str, int] = {}
        self._agent_id_to_oracle_id: dict[str, str] = {}
        self._env_event_times: dict[str, float] = {}

    def judge_turn(self, turn_idx: int, agent_events: list[CompletedEvent]) -> JudgmentResult:
        """Judge a single turn. Called by EventProcessor.

        Returns JudgmentResult with success flag and ID mapping.
        """
        for ev in agent_events:
            if ev.event_type == 'ENV' and ev.event_id:
                self._env_event_times[ev.event_id] = ev.event_time
        agent_events = [ev for ev in agent_events if ev.action is not None and ev.action.operation_type == 'write' and (ev.event_type not in ('ENV', 'USER'))]
        if turn_idx >= len(self.turn_to_oracle_events):
            pass
            return JudgmentResult(success=True)
        oracle_events = self.turn_to_oracle_events[turn_idx]
        oracle_graph = self.turn_to_oracle_graph[turn_idx]
        if not oracle_events:
            pass
            return JudgmentResult(success=True)
        self._normalize_agent_tool_names(agent_events)
        base_idx = len(self._all_agent_events)
        self._all_agent_events.extend(agent_events)
        pass
        prelim = self._preliminary_checks(agent_events, oracle_events)
        if prelim is not True:
            reason = prelim
            pass
            result = JudgmentResult(success=False, failure_reason=str(reason))
            self._log_judgment(turn_idx, result, agent_events, oracle_events)
            return result
        match_details: list[dict] = []
        first_failure: str | None = None
        for oracle_event in oracle_events:
            oracle_event = self._resolve_oracle_placeholders(oracle_event)
            matched, reason, judge_output = self._match_oracle_event(oracle_event, oracle_graph, agent_events, base_idx, turn_idx)
            match_details.append({'oracle_id': oracle_event.event_id, 'oracle_tool': oracle_event.tool_name(), 'matched': matched, 'reason': reason, 'judge_output': judge_output})
            if not matched:
                pass
                if first_failure is None:
                    first_failure = reason
        mapping = dict(self._agent_id_to_oracle_id)
        if first_failure is not None:
            result = JudgmentResult(success=False, failure_reason=first_failure, agent_event_id_to_oracle_event_id=mapping)
            self._log_judgment(turn_idx, result, agent_events, oracle_events, match_details)
            return result
        pass
        result = JudgmentResult(success=True, agent_event_id_to_oracle_event_id=mapping)
        self._log_judgment(turn_idx, result, agent_events, oracle_events, match_details)
        return result

    def _log_judgment(self, turn_idx: int, result: JudgmentResult, agent_events: list[CompletedEvent], oracle_events: list[OracleEvent], match_details: list[dict] | None=None) -> None:
        """Append structured judgment record to judgments.jsonl."""
        if self._judgments_path is None:
            return
        record = {'turn': turn_idx, 'success': result.success, 'failure_reason': result.failure_reason or None, 'agent_events': [{'id': e.event_id, 'tool': e.tool_name(), 'args': {k: str(v) if not isinstance(v, (str, int, float, bool, type(None))) else v for k, v in (e.get_args() or {}).items()}, 'args_summary': {k: str(v)[:80] if isinstance(v, str) else v for k, v in (e.get_args() or {}).items()}} for e in agent_events], 'oracle_events': [{'id': e.event_id, 'tool': e.tool_name(), 'args': {k: str(v) if not isinstance(v, (str, int, float, bool, type(None))) else v for k, v in (e.get_args() or {}).items()}, 'args_summary': {k: str(v)[:80] if isinstance(v, str) else v for k, v in (e.get_args() or {}).items()}} for e in oracle_events], 'match_details': match_details, 'id_mapping': result.agent_event_id_to_oracle_event_id or None}
        with open(self._judgments_path, 'a') as f:
            f.write(json.dumps(record) + '\n')
        pass

    def _preliminary_checks(self, agent_events: list[CompletedEvent], oracle_events: list[OracleEvent]) -> bool | str:
        """Check tool call counts match. Returns True or failure string.

        send_message_to_user is allowed to appear more times than in
        the oracle (controlled by ``extra_smu_allowed``) because the
        adapter may inject turn-boundary AUI events.  But oracle SMU
        events still go through the full matching pipeline so their
        content gets validated by the user_message_checker.
        """
        aui_name = 'AgentUserInterface__send_message_to_user'
        agent_counter = Counter((e.tool_name() for e in agent_events))
        oracle_counter = Counter((e.tool_name() for e in oracle_events))
        agent_aui = agent_counter.get(aui_name, 0)
        oracle_aui = oracle_counter.get(aui_name, 0)
        if not oracle_aui <= agent_aui <= oracle_aui + self.extra_smu_allowed:
            return f'SMU count mismatch: agent={agent_aui}, oracle={oracle_aui}, allowed_extra={self.extra_smu_allowed}'
        agent_other = Counter({k: v for k, v in agent_counter.items() if k != aui_name})
        oracle_other = Counter({k: v for k, v in oracle_counter.items() if k != aui_name})
        if agent_other != oracle_other:
            return f'Tool count mismatch: agent={dict(agent_other)}, oracle={dict(oracle_other)}'
        return True

    def _check_event_time(self, agent_time: float, oracle_time: float) -> bool:
        """Check if agent event time is within tolerance of oracle time."""
        return agent_time >= oracle_time - self._pre_event_tolerance and agent_time <= oracle_time + self._post_event_tolerance

    def _check_time(self, agent_event: CompletedEvent, oracle_event: OracleEvent, max_parent_agent_time: float) -> bool:
        """Check if the agent acted within the oracle's expected time window.

        Uses ``event_relative_time`` (from the scenario JSON) as the
        oracle's expected delay from its parent event.  The agent's
        actual delay is computed as the wall-clock gap between the agent
        event and its matched parent agent event.

        Only enforces timing when ``event_relative_time > threshold``.
        """
        oracle_relative = oracle_event.event_relative_time
        if oracle_relative is None or oracle_relative <= self._check_time_threshold:
            return True
        agent_relative = agent_event.event_time - max_parent_agent_time
        return self._check_event_time(agent_relative, oracle_relative)

    def _match_oracle_event(self, oracle_event: OracleEvent, oracle_graph: dict[str, list[str]], agent_events: list[CompletedEvent], base_idx: int, turn_idx: int) -> tuple[bool, str, str]:
        """Try to match an oracle event with an unmatched agent event."""
        if oracle_event.event_type in ('ENV', 'USER'):
            return self._match_env_oracle_event(oracle_event, agent_events, base_idx)
        return self._match_agent_oracle_event(oracle_event, oracle_graph, agent_events, base_idx, turn_idx)

    def _match_env_oracle_event(self, oracle_event: OracleEvent, agent_events: list[CompletedEvent], base_idx: int) -> tuple[bool, str, str]:
        """Match ENV/USER oracle event by event_id equality."""
        for i, agent_event in enumerate(agent_events):
            if agent_event.event_id == oracle_event.event_id:
                global_idx = base_idx + i
                self._record_match(global_idx, oracle_event.event_id, agent_event.event_id)
                return (True, '', '')
        return (False, f'ENV event {oracle_event.event_id} not found in agent events', '')

    def _match_agent_oracle_event(self, oracle_event: OracleEvent, oracle_graph: dict[str, list[str]], agent_events: list[CompletedEvent], base_idx: int, turn_idx: int) -> tuple[bool, str, str]:
        """Match AGENT oracle event using tool judges + causality + time."""
        oracle_tool = oracle_event.tool_name()
        failures: list[str] = []
        last_judge_output = ''
        for i, agent_event in enumerate(agent_events):
            global_idx = base_idx + i
            if global_idx in self._agent_idx_to_oracle_id:
                continue
            matched, rationale, judge_output = mild_compare(agent_event=agent_event, oracle_event=oracle_event, arg_checker_registry=self._arg_registry, soft_checker_registry=self._soft_registry, llm_checkers=self._llm_checkers, tolerance_list_str=self._get_tolerance_list(), tasks=self.tasks[:turn_idx + 1] if self.tasks else None, user_details=self.user_details, scenario_start_time=self.start_time)
            if judge_output:
                last_judge_output = judge_output
            if matched is None:
                failures.append(f'{agent_event.event_id}: inconclusive ({rationale})')
                continue
            if not matched:
                if agent_event.tool_name() == oracle_tool:
                    failures.append(f'{agent_event.event_id}: {rationale}')
                continue
            causality_ok = True
            parent_ids = oracle_graph.get(oracle_event.event_id, [])
            for parent_id in parent_ids:
                parent_agent_idx = self._oracle_id_to_agent_idx.get(parent_id)
                if parent_agent_idx is None or parent_agent_idx >= global_idx:
                    causality_ok = False
                    failures.append(f'{agent_event.event_id}: causality violation (parent {parent_id} not matched before idx {global_idx})')
                    break
            if not causality_ok:
                continue
            if oracle_event.event_relative_time is not None:
                max_parent_agent_time = self.start_time
                has_parent = False
                for pid in parent_ids:
                    agent_idx = self._oracle_id_to_agent_idx.get(pid)
                    if agent_idx is not None:
                        has_parent = True
                        max_parent_agent_time = max(max_parent_agent_time, self._all_agent_events[agent_idx].event_time)
                for dep_id in oracle_event.dependency_ids:
                    env_time = self._env_event_times.get(dep_id)
                    if env_time is not None:
                        has_parent = True
                        max_parent_agent_time = max(max_parent_agent_time, env_time)
                if not has_parent and oracle_event.dependency_ids:
                    has_parent = True
                if has_parent:
                    time_ok = self._check_time(agent_event, oracle_event, max_parent_agent_time)
                    if not time_ok:
                        if self._time_check_warn_only:
                            pass
                        else:
                            agent_rel = agent_event.event_time - max_parent_agent_time
                            failures.append(f'{agent_event.event_id}: time check failed (agent_relative={agent_rel:.0f}s, oracle_relative={oracle_event.event_relative_time:.0f}s)')
                            continue
            self._record_match(global_idx, oracle_event.event_id, agent_event.event_id)
            return (True, '', last_judge_output)
        failure_detail = '; '.join(failures) if failures else 'no candidates'
        return (False, f'Cannot match {oracle_tool} ({oracle_event.event_id}): {failure_detail}', last_judge_output)

    def _resolve_oracle_placeholders(self, oracle_event: OracleEvent) -> OracleEvent:
        """Replace {{oracle_id}} refs in oracle args with matched agent return values."""
        if not oracle_event.args:
            return oracle_event
        resolved = {}
        for arg_name, arg_value in oracle_event.args.items():
            if not isinstance(arg_value, str) or '{{' not in arg_value:
                resolved[arg_name] = arg_value
                continue
            import re
            match = re.match('^\\{\\{(.*?)\\}\\}$', arg_value.strip())
            if not match:
                resolved[arg_name] = arg_value
                continue
            parts = match.group(1).split('.')
            ref_oracle_id = parts[0]
            agent_idx = self._oracle_id_to_agent_idx.get(ref_oracle_id)
            if agent_idx is not None:
                value = self._all_agent_events[agent_idx].return_value
            elif ref_oracle_id in self.env_return_values:
                value = self.env_return_values[ref_oracle_id]
            else:
                pass
                resolved[arg_name] = arg_value
                continue
            for key in parts[1:]:
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    value = arg_value
                    break
            resolved[arg_name] = value
        oracle_event.resolved_args = resolved
        return oracle_event

    def _normalize_agent_tool_names(self, events: list[CompletedEvent]) -> None:
        """Ensure agent events use class_name (not app alias) in tool_name."""
        for ev in events:
            if ev.action is None:
                continue
            cls = self.app_name_to_class.get(ev.action.app_name)
            if cls and cls != ev.action.class_name:
                ev.action.class_name = cls

    def _get_tolerance_list(self) -> list[str]:
        """User name as tolerance for attendee checks."""
        if self.user_details is None:
            return []
        name = f'{self.user_details.first_name} {self.user_details.last_name}'.strip()
        return [name] if name else []

    def _record_match(self, agent_idx: int, oracle_id: str, agent_event_id: str) -> None:
        self._agent_idx_to_oracle_id[agent_idx] = oracle_id
        self._oracle_id_to_agent_idx[oracle_id] = agent_idx
        self._agent_id_to_oracle_id[agent_event_id] = oracle_id
        pass
